// Package ledger is what the public endpoints see of the membership ledger.
//
// A View answers reads and takes writes. Which store those go to is not the
// endpoints' business: it depends on how far the migration has got, so the
// endpoints ask the view and the view decides.
package ledger

import (
	"context"
	"errors"

	"membershipledger/internal/legacy"
)

// ErrWriteRefused is for an adjustment the ledger will not accept.
var ErrWriteRefused = errors.New("ledger writes are closed")

type View interface {
	Member(ctx context.Context, memberID string) (legacy.Member, error)
	Ledger(ctx context.Context, memberID string) ([]legacy.Entry, error)
	Adjust(ctx context.Context, memberID string, deltaCents int64, reason string) (legacy.Entry, legacy.Member, error)
}

package ledger

import (
	"context"
	"crypto/rand"
	"encoding/hex"

	"membershipledger/internal/clock"
	"membershipledger/internal/legacy"
)

// LegacyView answers from the legacy store and writes to it. This is how the
// ledger has always behaved and it is what the service starts up doing.
type LegacyView struct {
	Store *legacy.Store
	Clock *clock.Clock
}

func (v LegacyView) Member(ctx context.Context, memberID string) (legacy.Member, error) {
	return v.Store.Member(ctx, memberID)
}

func (v LegacyView) Ledger(ctx context.Context, memberID string) ([]legacy.Entry, error) {
	if _, err := v.Store.Member(ctx, memberID); err != nil {
		return nil, err
	}
	return v.Store.Ledger(ctx, memberID)
}

func (v LegacyView) Adjust(ctx context.Context, memberID string, deltaCents int64, reason string) (legacy.Entry, legacy.Member, error) {
	entry, err := v.Store.Append(ctx, memberID, NewEntryID(), reason, v.Clock.Stamp(), deltaCents)
	if err != nil {
		return legacy.Entry{}, legacy.Member{}, err
	}
	member, err := v.Store.Member(ctx, memberID)
	if err != nil {
		return entry, legacy.Member{}, err
	}
	return entry, member, nil
}

// NewEntryID mints a ledger entry identifier.
func NewEntryID() string {
	raw := make([]byte, 16)
	if _, err := rand.Read(raw); err != nil {
		return "entry-fallback"
	}
	return hex.EncodeToString(raw)
}

// Package migration moves the ledger from the legacy store to the destination
// store while production traffic keeps running.
package migration

// Phase names the stage the migration has reached. The order below is the only
// order the migration runs in; CUTOVER is the step that cannot be undone.
type Phase string

const (
	PhaseInit          Phase = "INIT"
	PhaseShadowCopy    Phase = "SHADOW_COPY"
	PhaseDualRead      Phase = "DUAL_READ"
	PhaseCatchUp       Phase = "CATCH_UP"
	PhaseReconcile     Phase = "RECONCILE"
	PhaseCutover       Phase = "CUTOVER"
	PhaseLateReplay    Phase = "LATE_REPLAY"
	PhaseLegacyRetired Phase = "LEGACY_RETIRED"
	PhaseComplete      Phase = "COMPLETE"
)

// Order is the phase sequence.
var Order = []Phase{
	PhaseInit,
	PhaseShadowCopy,
	PhaseDualRead,
	PhaseCatchUp,
	PhaseReconcile,
	PhaseCutover,
	PhaseLateReplay,
	PhaseLegacyRetired,
	PhaseComplete,
}

// Authority names the store a ledger movement is recorded in.
const (
	AuthorityLegacy      = "legacy"
	AuthorityDestination = "destination"
)

// Next is the phase that follows this one, and whether there is one.
func Next(phase Phase) (Phase, bool) {
	for index, candidate := range Order {
		if candidate == phase && index+1 < len(Order) {
			return Order[index+1], true
		}
	}
	return phase, false
}

// Index is a phase's position in Order, or -1.
func Index(phase Phase) int {
	for index, candidate := range Order {
		if candidate == phase {
			return index
		}
	}
	return -1
}

// Package clock is the service's only source of the current time.
//
// Deployments run this service with a controlled clock so that lease expiry
// and entry timestamps are reproducible: when a clock file is configured, the
// unix second it contains is the time, and it changes when the operator changes
// it. Nothing here touches any library's own timing — the database, the store
// service and the HTTP server all keep using real time internally. Code that
// reaches for time.Now() directly will disagree with the rest of the
// deployment about what time it is.
package clock

import (
	"os"
	"strconv"
	"strings"
	"sync"
	"time"
)

type Clock struct {
	mu   sync.Mutex
	path string
}

func New(path string) *Clock { return &Clock{path: path} }

// Now is the current time according to the deployment.
func (c *Clock) Now() time.Time {
	c.mu.Lock()
	path := c.path
	c.mu.Unlock()
	if path == "" {
		return time.Now().UTC()
	}
	blob, err := os.ReadFile(path)
	if err != nil {
		return time.Now().UTC()
	}
	seconds, err := strconv.ParseInt(strings.TrimSpace(string(blob)), 10, 64)
	if err != nil {
		return time.Now().UTC()
	}
	return time.Unix(seconds, 0).UTC()
}

// Unix is the current time in whole seconds, which is the unit leases and
// timestamps are expressed in.
func (c *Clock) Unix() int64 { return c.Now().Unix() }

// Stamp formats a time the way the ledger records it.
func (c *Clock) Stamp() string { return c.Now().Format("2006-01-02T15:04:05Z") }

// Package legacy is the ledger's original store. It is the system of record
// until the migration says otherwise: production traffic reads and writes here.
package legacy

import (
	"context"
	"database/sql"
	"errors"
	"fmt"

	_ "modernc.org/sqlite"
)

var ErrNotFound = errors.New("legacy: member not found")

type Member struct {
	MemberID     string `json:"member_id"`
	Tier         string `json:"tier"`
	BalanceCents int64  `json:"balance_cents"`
	Version      int64  `json:"version"`
	Deleted      bool   `json:"deleted"`
	UpdatedAt    string `json:"updated_at"`
}

type Entry struct {
	EntryID    string `json:"entry_id"`
	MemberID   string `json:"member_id"`
	Seq        int64  `json:"seq"`
	GlobalSeq  int64  `json:"global_seq"`
	DeltaCents int64  `json:"delta_cents"`
	Reason     string `json:"reason"`
	WrittenAt  string `json:"written_at"`
}

type Store struct {
	db *sql.DB
}

func Open(path string) (*Store, error) {
	db, err := sql.Open("sqlite", path+"?_pragma=busy_timeout(10000)&_pragma=journal_mode(WAL)")
	if err != nil {
		return nil, err
	}
	// One writer at a time: the ledger is small and correctness of the
	// per-member sequence matters more than write concurrency.
	db.SetMaxOpenConns(1)
	if err := db.Ping(); err != nil {
		return nil, err
	}
	return &Store{db: db}, nil
}

func (s *Store) Close() error { return s.db.Close() }

func (s *Store) Member(ctx context.Context, memberID string) (Member, error) {
	row := s.db.QueryRowContext(ctx, `
		SELECT member_id, tier, balance_cents, version, deleted, updated_at
		FROM members WHERE member_id = ?`, memberID)
	return scanMember(row)
}

func (s *Store) Members(ctx context.Context) ([]Member, error) {
	rows, err := s.db.QueryContext(ctx, `
		SELECT member_id, tier, balance_cents, version, deleted, updated_at
		FROM members ORDER BY member_id`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []Member
	for rows.Next() {
		var m Member
		var deleted int
		if err := rows.Scan(&m.MemberID, &m.Tier, &m.BalanceCents, &m.Version, &deleted, &m.UpdatedAt); err != nil {
			return nil, err
		}
		m.Deleted = deleted != 0
		out = append(out, m)
	}
	return out, rows.Err()
}

func (s *Store) Ledger(ctx context.Context, memberID string) ([]Entry, error) {
	rows, err := s.db.QueryContext(ctx, `
		SELECT entry_id, member_id, seq, global_seq, delta_cents, reason, written_at
		FROM ledger_entries WHERE member_id = ? ORDER BY seq`, memberID)
	if err != nil {
		return nil, err
	}
	return scanEntries(rows)
}

// EntriesAfter reads the append log forward from a global sequence position.
// This is the tail the ledger is replayed from.
func (s *Store) EntriesAfter(ctx context.Context, afterGlobalSeq int64, limit int) ([]Entry, error) {
	if limit <= 0 {
		limit = 500
	}
	rows, err := s.db.QueryContext(ctx, `
		SELECT entry_id, member_id, seq, global_seq, delta_cents, reason, written_at
		FROM ledger_entries WHERE global_seq > ? ORDER BY global_seq LIMIT ?`,
		afterGlobalSeq, limit)
	if err != nil {
		return nil, err
	}
	return scanEntries(rows)
}

func (s *Store) MaxGlobalSeq(ctx context.Context) (int64, error) {
	var value sql.NullInt64
	if err := s.db.QueryRowContext(ctx, `SELECT MAX(global_seq) FROM ledger_entries`).Scan(&value); err != nil {
		return 0, err
	}
	return value.Int64, nil
}

func (s *Store) EntryCount(ctx context.Context) (int64, error) {
	var count int64
	err := s.db.QueryRowContext(ctx, `SELECT COUNT(*) FROM ledger_entries`).Scan(&count)
	return count, err
}

// Append records one ledger movement: it allocates the member's next sequence
// number and the ledger's next global sequence number, writes the entry, and
// folds it into the member's balance, all in one transaction.
func (s *Store) Append(ctx context.Context, memberID, entryID, reason, writtenAt string, deltaCents int64) (Entry, error) {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return Entry{}, err
	}
	defer func() { _ = tx.Rollback() }()

	var exists int
	if err := tx.QueryRowContext(ctx, `SELECT COUNT(*) FROM members WHERE member_id = ?`, memberID).Scan(&exists); err != nil {
		return Entry{}, err
	}
	if exists == 0 {
		return Entry{}, ErrNotFound
	}

	var nextSeq, nextGlobal int64
	if err := tx.QueryRowContext(ctx,
		`SELECT COALESCE(MAX(seq), 0) + 1 FROM ledger_entries WHERE member_id = ?`, memberID,
	).Scan(&nextSeq); err != nil {
		return Entry{}, err
	}
	if err := tx.QueryRowContext(ctx,
		`SELECT COALESCE(MAX(global_seq), 0) + 1 FROM ledger_entries`,
	).Scan(&nextGlobal); err != nil {
		return Entry{}, err
	}

	entry := Entry{
		EntryID:    entryID,
		MemberID:   memberID,
		Seq:        nextSeq,
		GlobalSeq:  nextGlobal,
		DeltaCents: deltaCents,
		Reason:     reason,
		WrittenAt:  writtenAt,
	}
	if _, err := tx.ExecContext(ctx, `
		INSERT INTO ledger_entries
			(entry_id, member_id, seq, global_seq, delta_cents, reason, written_at)
		VALUES (?,?,?,?,?,?,?)`,
		entry.EntryID, entry.MemberID, entry.Seq, entry.GlobalSeq,
		entry.DeltaCents, entry.Reason, entry.WrittenAt); err != nil {
		return Entry{}, err
	}
	if _, err := tx.ExecContext(ctx, `
		UPDATE members
		SET balance_cents = balance_cents + ?, version = version + 1, updated_at = ?
		WHERE member_id = ?`, entry.DeltaCents, entry.WrittenAt, entry.MemberID); err != nil {
		return Entry{}, err
	}
	if err := tx.Commit(); err != nil {
		return Entry{}, fmt.Errorf("legacy append commit: %w", err)
	}
	return entry, nil
}

func scanMember(row *sql.Row) (Member, error) {
	var m Member
	var deleted int
	err := row.Scan(&m.MemberID, &m.Tier, &m.BalanceCents, &m.Version, &deleted, &m.UpdatedAt)
	if errors.Is(err, sql.ErrNoRows) {
		return m, ErrNotFound
	}
	if err != nil {
		return m, err
	}
	m.Deleted = deleted != 0
	return m, nil
}

func scanEntries(rows *sql.Rows) ([]Entry, error) {
	defer rows.Close()
	var out []Entry
	for rows.Next() {
		var e Entry
		if err := rows.Scan(&e.EntryID, &e.MemberID, &e.Seq, &e.GlobalSeq,
			&e.DeltaCents, &e.Reason, &e.WrittenAt); err != nil {
			return nil, err
		}
		out = append(out, e)
	}
	return out, rows.Err()
}

